// Check all K12 services and return a health summary
const services = [
  { name: 'Ollama',       url: 'http://192.168.1.168:11434/api/tags' },
  { name: 'Open WebUI',  url: 'http://192.168.1.168:8000' },
  { name: 'n8n',         url: 'http://192.168.1.168:3001/healthz' },
  { name: 'Qdrant',      url: 'http://192.168.1.168:6333/health' },
  { name: 'MCP Server',  url: 'http://192.168.1.168:3005/health' },
  { name: 'Langfuse',    url: 'http://192.168.1.168:8888/api/public/health' },
  { name: 'Hermes',      url: 'http://192.168.1.168:9119/' },
  { name: 'Whisper STT', url: 'http://192.168.1.168:9000/docs' },
  { name: 'Kokoro TTS',  url: 'http://192.168.1.168:8880/health' },
  { name: 'Infra Dash',  url: 'http://192.168.1.168:7000' },
];

const results = [];
const failed = [];

for (const svc of services) {
  try {
    await this.helpers.httpRequest({ method: 'GET', url: svc.url, timeout: 5000 });
    results.push(`✅ ${svc.name}`);
  } catch (e) {
    results.push(`❌ ${svc.name}`);
    failed.push(svc.name);
  }
}

const statusLine = failed.length === 0
  ? 'All systems operational.'
  : `${failed.length} service(s) down: ${failed.join(', ')}`;

return [{
  json: {
    healthReport: results.join('\n'),
    statusLine,
    failedCount: failed.length,
    date: new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })
  }
}];

